// s(tag, [en title, en body, en idea], [vi title, vi body, vi idea], activeNodes, activeEdges, metricValues)
const s = (tag, en, vi, nodes, edges, values) => ({
  tag,
  title: T(en[0], vi[0]),
  body: T(en[1], vi[1]),
  idea: T(en[2], vi[2]),
  nodes,
  edges,
  values: [...values, ...Array(Math.max(0, 4 - values.length)).fill("—")].slice(0, 4),
});

const lesson = (id, chapter, title, summary, minutes, level, diagram, metrics, goals, steps) => ({
  id, chapter, title: T(...title), summary: T(...summary), minutes, level, diagram, metrics, goals, steps,
});

